FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; // Variable de entrada que indica si hay una condición de alarma
END_VAR

VAR_OUTPUT
    lampara : BOOL; // Variable de salida que controla el estado de la lámpara
END_VAR

VAR
    temporizador : TON; // Temporizador para controlar el parpadeo
    estado_parpadeo : BOOL; // Estado interno para alternar el parpadeo
END_VAR

// Inicialización del temporizador
temporizador(IN := estado_parpadeo, PT := T#1S);

IF alarma THEN
    // Si hay alarma, activar el temporizador
    temporizador(IN := NOT temporizador.Q);

    // Alternar el estado de parpadeo cuando el temporizador termina
    IF temporizador.Q THEN
        estado_parpadeo := NOT estado_parpadeo;
    END_IF;

    // La lámpara sigue el estado de parpadeo
    lampara := estado_parpadeo;
ELSE
    // Si no hay alarma, apagar la lámpara y reiniciar el temporizador
    lampara := FALSE;
    estado_parpadeo := FALSE;
    temporizador(IN := FALSE);
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL;       // Sensor de nivel para el componente A
    nivelB : BOOL;       // Sensor de nivel para el componente B
    nivelVacio : BOOL;   // Sensor de nivel para el estado vacío
    btnInicio : BOOL;    // Botón de inicio
    btnAbort : BOOL;     // Botón de aborto
    temp : REAL;         // Temperatura actual del reactor
END_VAR

VAR_OUTPUT
    vA : BOOL;           // Válvula para dosificar componente A
    vB : BOOL;           // Válvula para dosificar componente B
    calentador : BOOL;   // Calentador del reactor
    mezclador : BOOL;    // Mezclador del reactor
    vDescarga : BOOL;    // Válvula de descarga
    fase : INT;          // Fase actual del proceso
END_VAR

VAR
    timerMezcla : TON;   // Temporizador para la fase de mezcla
    inicioPrev : BOOL;   // Estado previo del botón de inicio
    abortPrev : BOOL;    // Estado previo del botón de aborto
END_VAR

// Inicialización
IF NOT btnInicio THEN
    inicioPrev := FALSE;
END_IF

IF NOT btnAbort THEN
    abortPrev := FALSE;
END_IF

// Control de fases
CASE fase OF
    0: // Reposo
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF btnInicio AND NOT inicioPrev THEN
            fase := 1;
        END_IF

    1: // Fase 1: Dosificación de A
        vA := TRUE;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF

    2: // Fase 2: Dosificación de B
        vB := TRUE;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF

    3: // Fase 3: Calentamiento
        calentador := TRUE;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF

    4: // Fase 4: Mezcla
        mezclador := TRUE;
        timerMezcla(IN := TRUE, PT := T#120S);
        IF timerMezcla.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF

    5: // Fase 5: Descarga
        vDescarga := TRUE;
        IF nivelVacio THEN
            vDescarga := FALSE;
            fase := 0;
        END_IF
END_CASE

// Manejo del botón de aborto
IF btnAbort AND NOT abortPrev THEN
    vA := FALSE;
    vB := FALSE;
    calentador := FALSE;
    mezclador := FALSE;

    IF NOT nivelVacio THEN
        fase := 5;
    ELSE
        fase := 0;
    END_IF
END_IF

// Actualización de estados previos
inicioPrev := btnInicio;
abortPrev := btnAbort;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Entrada para habilitar el semáforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    tVerde : TP; (* Temporizador para luz verde *)
    tAmarillo : TP; (* Temporizador para luz amarilla *)
    tRojo : TP; (* Temporizador para luz roja *)
    tIntermitente : TP; (* Temporizador para luz amarilla intermitente *)
    estado : INT := 0; (* Variable de estado para la secuencia del semáforo *)
END_VAR

(* Secuencia del semáforo cuando está habilitado *)
IF habilitado THEN
    CASE estado OF
        0: (* Estado verde *)
            tVerde(IN := TRUE, PT := T#20S);
            luzV := tVerde.Q;
            luzA := FALSE;
            luzR := FALSE;
            IF tVerde.Q THEN
                estado := 1;
            END_IF
        1: (* Estado amarillo *)
            tAmarillo(IN := TRUE, PT := T#4S);
            luzV := FALSE;
            luzA := tAmarillo.Q;
            luzR := FALSE;
            IF tAmarillo.Q THEN
                estado := 2;
            END_IF
        2: (* Estado rojo *)
            tRojo(IN := TRUE, PT := T#15S);
            luzV := FALSE;
            luzA := FALSE;
            luzR := tRojo.Q;
            IF tRojo.Q THEN
                estado := 0;
            END_IF
    END_CASE
ELSE
    (* Secuencia del semáforo cuando no está habilitado *)
    tIntermitente(IN := TRUE, PT := T#1S);
    luzV := FALSE;
    luzR := FALSE;
    luzA := tIntermitente.Q;
    IF tIntermitente.Q THEN
        tIntermitente(IN := FALSE);
    ELSE
        tIntermitente(IN := TRUE);
    END_IF
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Alarmas
VAR_INPUT
    alm1 : BOOL; (* Alarma de prioridad alta *)
    alm2 : BOOL; (* Alarma de prioridad media *)
    alm3 : BOOL; (* Alarma de prioridad baja *)
    ack1 : BOOL; (* Reconocimiento de alarma 1 *)
    ack2 : BOOL; (* Reconocimiento de alarma 2 *)
    ack3 : BOOL; (* Reconocimiento de alarma 3 *)
END_VAR
VAR_OUTPUT
    sirena : BOOL; (* Sirena *)
    codigoAlm : INT; (* Código de la alarma de mayor prioridad *)
END_VAR
VAR
    retAlm1 : BOOL; (* Retención de alarma 1 *)
    retAlm2 : BOOL; (* Retención de alarma 2 *)
    retAlm3 : BOOL; (* Retención de alarma 3 *)
END_VAR

(* Retención de alarmas *)
IF NOT ack1 THEN
    retAlm1 := alm1;
ELSE
    retAlm1 := FALSE;
END_IF;

IF NOT ack2 THEN
    retAlm2 := alm2;
ELSE
    retAlm2 := FALSE;
END_IF;

IF NOT ack3 THEN
    retAlm3 := alm3;
ELSE
    retAlm3 := FALSE;
END_IF;

(* Determinación de la alarma de mayor prioridad *)
IF retAlm1 THEN
    sirena := TRUE;
    codigoAlm := 1;
ELSIF retAlm2 THEN
    sirena := TRUE;
    codigoAlm := 2;
ELSIF retAlm3 THEN
    sirena := TRUE;
    codigoAlm := 3;
ELSE
    sirena := FALSE;
    codigoAlm := 0;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL; // Botón de paro
END_VAR

VAR_OUTPUT
    kM : BOOL; // Contactor principal
    kY : BOOL; // Contactor de estrella
    kD : BOOL; // Contactor de triángulo
END_VAR

VAR
    timerStar : TON; // Temporizador para el contacto de estrella
    timerDelta : TON; // Temporizador para el contacto de triángulo
    state : INT := 0; // Estado actual del programa
    deadTime : TON; // Temporizador para el tiempo muerto
END_VAR

// Inicialización de temporizadores
timerStar(IN := FALSE, PT := T#8S);
timerDelta(IN := FALSE, PT := T#100MS);
deadTime(IN := FALSE, PT := T#100MS);

// Lógica del programa
CASE state OF
    0: // Estado inicial
        IF btnMarcha THEN
            kM := TRUE;
            kY := TRUE;
            timerStar(IN := TRUE);
            state := 1;
        END_IF
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF

    1: // Esperando para desactivar kY
        IF timerStar.Q THEN
            kY := FALSE;
            timerStar(IN := FALSE);
            deadTime(IN := TRUE);
            state := 2;
        END_IF
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF

    2: // Tiempo muerto
        IF deadTime.Q THEN
            kD := TRUE;
            deadTime(IN := FALSE);
            state := 3;
        END_IF
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF

    3: // Estado final
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF
END_CASE
